#[path = "solution.rs"]
mod solution;

use solution::{generate_record, FieldKind, FieldSpec, GenerateError, RecordSpec};

fn field(name: &str, kind: FieldKind) -> FieldSpec {
    FieldSpec { name: name.to_owned(), kind }
}

#[test]
fn generates_exact_struct_text_and_preserves_field_order() {
    let spec = RecordSpec {
        name: "Packet_2".to_owned(),
        fields: vec![
            field("tag", FieldKind::U8),
            field("offset", FieldKind::I32),
            field("enabled", FieldKind::Bool),
            field("data", FieldKind::Bytes),
        ],
    };
    let original = spec.clone();

    assert_eq!(
        generate_record(&spec),
        Ok("#[derive(Clone, Debug, PartialEq, Eq)]\npub struct Packet_2 {\n    pub tag: u8,\n    pub offset: i32,\n    pub enabled: bool,\n    pub data: Vec<u8>,\n}\n".to_owned())
    );
    assert_eq!(spec, original);
}

#[test]
fn generates_an_empty_record_with_required_final_newline() {
    let spec = RecordSpec { name: "_Empty".to_owned(), fields: Vec::new() };
    assert_eq!(
        generate_record(&spec),
        Ok("#[derive(Clone, Debug, PartialEq, Eq)]\npub struct _Empty {\n}\n".to_owned())
    );
}

#[test]
fn validates_record_name_before_fields() {
    let spec = RecordSpec {
        name: "2Bad".to_owned(),
        fields: vec![field("also-bad", FieldKind::U8)],
    };
    assert_eq!(generate_record(&spec), Err(GenerateError::InvalidIdentifier("2Bad".to_owned())));
}

#[test]
fn returns_first_invalid_field_identifier() {
    let spec = RecordSpec {
        name: "Valid".to_owned(),
        fields: vec![
            field("good", FieldKind::U8),
            field("bad-name", FieldKind::Bool),
            field("3bad", FieldKind::I32),
        ],
    };
    assert_eq!(generate_record(&spec), Err(GenerateError::InvalidIdentifier("bad-name".to_owned())));
}

#[test]
fn rejects_empty_non_ascii_and_keyword_identifiers() {
    for invalid in ["", "éclair", "struct", "fn", "self", "crate"] {
        let spec = RecordSpec { name: invalid.to_owned(), fields: Vec::new() };
        assert_eq!(generate_record(&spec), Err(GenerateError::InvalidIdentifier(invalid.to_owned())));
    }

    let spec = RecordSpec {
        name: "Valid".to_owned(),
        fields: vec![field("type", FieldKind::U8)],
    };
    assert_eq!(generate_record(&spec), Err(GenerateError::InvalidIdentifier("type".to_owned())));
}

#[test]
fn duplicate_is_reported_for_second_occurrence() {
    let spec = RecordSpec {
        name: "Valid".to_owned(),
        fields: vec![
            field("same", FieldKind::U8),
            field("other", FieldKind::Bool),
            field("same", FieldKind::Bytes),
        ],
    };
    assert_eq!(generate_record(&spec), Err(GenerateError::DuplicateField("same".to_owned())));
}

